// Generated by fluxora generate (Rebuild). Change orchestrator/templates, not this file.
// Data-driven: every case in fixtures/claim-triage/reference-cases.json runs through the Evaluator.
// Expected values come only from that file; nothing is hand-written here.

using System.Text.Json;

namespace Fluxora.Generated.Tests;

public class ReferenceCaseTests
{
    private static readonly JsonSerializerOptions Web = new(JsonSerializerDefaults.Web);
    private static readonly Lazy<Dictionary<string, JsonElement>> Cases = new(LoadCases);

    public static IEnumerable<object[]> CaseIds() => Cases.Value.Keys.Select(id => new object[] { id });

    [Theory]
    [MemberData(nameof(CaseIds))]
    public void ReferenceCase(string caseId)
    {
        var testCase = Cases.Value[caseId];
        var ruleIds = string.Join(",", testCase.GetProperty("ruleIds").EnumerateArray().Select(r => r.GetString()));
        var inputs = testCase.GetProperty("inputs");
        var expected = testCase.GetProperty("expected");

        // Bind the inputs exactly as the API does (web JSON defaults, decimal money, DateOnly dates).
        var request = inputs.Deserialize<EvaluateRequest>(Web)!;
        var today = DateOnly.Parse(inputs.GetProperty("today").GetString()!);
        var actual = Evaluator.Evaluate(request, today);

        var failures = new List<string>();
        void Check(string field, object? want, object? got)
        {
            if (!Equals(want, got)) failures.Add($"{field}: expected {Show(want)}, got {Show(got)}");
        }

        var wantErrors = expected.GetProperty("errors").EnumerateArray().Select(e => e.GetString()!).ToHashSet();
        if (!wantErrors.SetEquals(actual.Errors))
        {
            failures.Add($"errors: expected [{string.Join(",", wantErrors.Order())}], got [{string.Join(",", actual.Errors)}]");
        }
        Check("excess", Money(expected.GetProperty("excess")), actual.Excess);
        Check("payable", Money(expected.GetProperty("payable")), actual.Payable);
        Check("lateReport", Flag(expected.GetProperty("lateReport")), actual.LateReport);
        Check("status", expected.GetProperty("status").GetString(), actual.Status);

        Assert.True(failures.Count == 0, $"Case {caseId} (rules {ruleIds}) failed:\n  " + string.Join("\n  ", failures));
    }

    private static decimal? Money(JsonElement e) => e.ValueKind == JsonValueKind.Null ? null : e.GetDecimal();

    private static bool? Flag(JsonElement e) => e.ValueKind == JsonValueKind.Null ? null : e.GetBoolean();

    private static string Show(object? value) => value switch
    {
        null => "null",
        string s => $"\"{s}\"",
        _ => Convert.ToString(value, System.Globalization.CultureInfo.InvariantCulture)!,
    };

    private static Dictionary<string, JsonElement> LoadCases()
    {
        var dir = new DirectoryInfo(AppContext.BaseDirectory);
        while (dir is not null && !File.Exists(Path.Combine(dir.FullName, "fixtures", "claim-triage", "reference-cases.json")))
        {
            dir = dir.Parent;
        }
        if (dir is null)
        {
            throw new FileNotFoundException("Could not find fixtures/claim-triage/reference-cases.json above " + AppContext.BaseDirectory);
        }
        using var doc = JsonDocument.Parse(File.ReadAllText(Path.Combine(dir.FullName, "fixtures", "claim-triage", "reference-cases.json")));
        return doc.RootElement.GetProperty("cases").EnumerateArray()
            .ToDictionary(c => c.GetProperty("id").GetString()!, c => c.Clone());
    }
}
